 * Construct a complete bipartite graph
 */
@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the target graph is a bipartite graph and has more than
    // one vertex
    if (!target.isBipartite() || target.vertexCount() < 2) {
        throw new IllegalArgumentException("Target graph is not a bipartite graph or has fewer than 2 vertices");
    }

    // Get the number of vertices in the bipartite graph
    int numVertices = target.vertexCount();

    // Get the number of edges in the bipartite graph
    int numEdges = target.edgeCount();

    // Create an array to store the edges
    List<GraphEdge<V, E>> edges = new ArrayList<>(numEdges);

    // Get the graph nodes and create a map to store the nodes
    GraphNode<V, E>[] nodes = target.getNodes();
    HashMap<String, GraphNode<V, E>> nodeMap = new HashMap<>(nodes.length);
    for (GraphNode<V, E> node : nodes) {
        nodeMap.put(node.toString(), node);
    }

    // Get the vertices in the bipartite graph
    V[] vertices = target.getVertices();

    // Add edges to the graph
    for (int i = 0; i < numVertices; i++) {
        for (int j = i + 1; j < numVertices; j++) {
            // If the vertices are in the same partition, add an edge
            if (nodeMap.containsKey(vertices[i].toString()) && nodeMap.containsKey(vertices[j].toString())) {
                GraphEdge<V, E> edge = new GraphEdge<>(nodeMap.get(vertices[i].toString()), nodeMap.get(vertices[j].toString()));
                edges.add(edge);
            }
        }
    }

    // Add the edges to the graph
    for (GraphEdge<V, E> edge : edges) {
        target.addEdge(edge);
    }

    // Return the result map
    return resultMap;
}

