* Compresses the time bucket literal long value by following the day step.
*
* @param timeBucket the time bucket literal long value.
* @param dayStep the day step to follow.
* @return the compressed time bucket.
*/
public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day number for the given time bucket
    int dayNumber = (int)(timeBucket % 10000000000);

    // Calculate the new day number based on the day step
    int newDayNumber = dayNumber - (dayNumber % dayStep);

    // Return the compressed time bucket
    return (timeBucket / 10000000000) * 10000000000 + newDayNumber;
}

