private List<Pair<Integer,Integer>> computeMinimalSeparator(E edge) {
    // Get the vertices connected to the edge
    Integer u = graph.getEdgeSource(edge);
    Integer v = graph.getEdgeTarget(edge);

    // Compute the list of all vertices in the neighborhood of the edge
    Set<Integer> neighbors = graph.neighborsOf(edge);
    neighbors.add(u);
    neighbors.add(v);

