    /**
     * Returns the index of the last extension separator character, which is a dot. <p> This method also checks that there is no directory separator after the last dot. To do this it uses  {@link #indexOfLastSeparator(String)} which willhandle a file in either Unix or Windows format. <p> The output will be the same irrespective of the machine that the code is running on.
     * @param filename  the filename to find the last path separator in, null returns -1
     * @return the index of the last separator character, or -1 if thereis no such character
     */
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int loc0 = indexOfLastSeparator(filename);
        if (loc0 < filename.length() - 1) {
            return filename.substring(loc0 + 1).lastIndexOf(UNIX_SEPARATOR);
        } else {
            return -1;
        }
    }

    /**
     * Returns the index of the last directory separator character, either backslash or forward slash. <p> This method also checks that there is no extension separator after the last directory separator. To do this it uses  {@link #indexOfExtension(String)} which will handle a file in either Unix or Windows format. <p> The output will be the same irrespective of the machine that the code is running on.
     * @param filename  the filename to find the last path separator in, null returns -1
     * @return the index of the last separator character, or -1 if thereis no such character
     */
    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int loc0 = filename.lastIndexOf(UNIX_SEPARATOR);
        if (loc0 == -1 || loc0 < filename.length() - 1) {
            loc0 = filename.lastIndexOf(WINDOWS_SEPARATOR);
            if (loc0 == -1 || loc0 < filename.length - 1) {
                return -1;
            }
        }
        int loc1 = Math.min(loc0, filename.length() - 1);
        if (filename.substring(loc1 + 1).contains(extensionSeparator)) {
            return -1;
        }
        return loc1;
    }

    /**
     * Returns whether the given file path ends with the given extension regardless of case.
     * Always use this method instead of {@link String#endsWith(String)} to ensure correctness when the extension may contain dots (.).
     * @param path  the full path to check
     * @param extension  the extension to check for, null returns false
     * @return true if the  filesystem path ends with the specified extension
     */
    public static boolean endsWithExtension (String path, String extension) {
        if (path == null || extension == null) {
            return false;
        }
        return path.regionMatches(true, path.length() - extension.length(), extension, 0, extension.length());
    }
}

