    if (hasMoreNodes()) {
        nextNode = nextNode();
    }

    // Check if the next node is real or virtual
    if (nextNode instanceof RealNode) {
        // Return an edge incident to the real next node
        return new Edge(this, nextNode);
    } else {
        // Get the real node
