static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

	// Check if the file exists and is a regular file
	if (!file.exists() || !file.isFile()) {
	throw new IOException("File not found or is not a regular file");
	}

	// Create a new list to store the thread snapshots
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

	// Open the file using a BufferedReader
	try (BufferedReader reader = new BufferedReader(new FileReader(file))) {

	// Read the file line by line
	String line;
	while ((line = reader.readLine()) != null) {

	// Parse the line as a JSON object
	JSONObject jsonObject = new JSONObject(line);

	// Check if the line is a thread snapshot
	if (jsonObject.getBoolean("type") == "THREAD_SNAPSHOT") {

	// Get the thread name and timestamp
	String threadName = jsonObject.getString("thread_name");
	Long timestamp = jsonObject.getLong("timestamp");

	// Check if the timestamp is within the desired time range
	for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
	if (timeRange.getStartMillis() <= timestamp && timestamp <= timeRange.getEndMillis()) {

	// Create a new thread snapshot with the thread name and timestamp
	ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, timestamp);

	// Add the thread snapshot to the list
	threadSnapshots.add(threadSnapshot);

	// Break out of the loop since the time range has been found
	break;
	}
	}

	}

	}

	// Return the list of thread snapshots
	return threadSnapshots;
 }

	// Catch any exceptions that may occur while reading the file
	catch (Exception e) {
	e.printStackTrace();
	}

	// Return an empty list if the file could not be read
	return new ArrayList<>();
}

Please note that this method assumes that the thread snapshot data is in a JSON format, and it may require modifications to accommodate different data formats. Additionally, this method does not validate the data it reads, so it is the responsibility of the caller to ensure that the data is valid and meets the expected format.
